#!/usr/bin/env bash
# Some portions generated by Codex. Test-only memo observer overlay is qualification-only.
set -euo pipefail
cd "$(dirname "$0")/../../.."
D=experiments/threadlocal-audit/resource-holder
FIX=experiments/threadlocal-audit/resource-restoration/grouped-fix
exec 9>experiments/overlay/native-benchmark.lock
flock 9
for arm in a ad; do
 cp="$PWD/$FIX/classes:$PWD/$D/candidate-layer:$(cat experiments/threadlocal-audit/read-depth/cp_${arm}.txt)"
 printf '%s\n' "$cp" > "$D/gated-$arm.classpath.txt"
 ../toolchain/jdk-25.0.5+8/bin/java -Xmx4g --enable-native-access=ALL-UNNAMED \
 -Drdf4j.lmdb.nativeValueMemo.testProbe=true -Drdf4j.lmdb.nativeValueMemo.enabled=true \
 -Drdf4j.lmdb.janinoCodegen.synchronous=true -cp "$cp" GatedLauncher > "$D/gated-$arm.log" 2>&1
 echo "gated_arm=$arm exit=0"
done
